#define MAX_DIST 100.
#define SURF_DIST .0001
#define EPS .0001
#define PI 3.14
#define PI2 6.28
#define saturate(a) clamp(a,0.,1.)
#define S(a,b,t) smoothstep(a,b,t)
#define TS(a,b,c,d,t) smoothstep(a,b,t) * smoothstep(d,c,t)

// https://iquilezles.org/articles/palettes/
vec3 palette(float t)
{
    vec3 a = vec3(.1, .3, .8);
    vec3 b = vec3(.8, .4, .1);
    vec3 c = vec3(.4, .8, .9);
    vec3 d = vec3(.2, .9, .6);
    return a + b*cos( 6.283185*(c*t+d) );
}

// NOTE: I realized later that there was a bug, but I'll leave it at that...
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, s, -s, c);
}

vec2 pmod(vec2 p, float s) {
    float a = PI / s - atan(p.x, p.y);
    float n = PI2 / s;
    a = floor(a / n) * n;
    p *= rot(a);
    return p;
}

float sdSphere(vec3 p, float s) {
    return length(p) - s;
}

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.);
}

float sdRoundBox(vec3 p, vec3 b, float r)
{
    vec3 q = abs(p) - b + r;
    return length(max(q, 0.)) + min(max(q.x, max(q.y, q.z)), 0.) - r;
}

float opUnion(float d1, float d2) {
    return min(d1, d2);
}

// d2 から d1 を引く
float opSub(float d1, float d2) {
    return max(-d1, d2);
}

float opSmooth(float d1, float d2, float k)
{
    float h = clamp(.5 + .5 *(d2 - d1) / k, 0., 1.);
    return mix(d2, d1, h) - k * h * (1. - h);
}

float opSmoothSub(float d1, float d2, float k)
{
    float h = clamp(.5 - .5 * (d2 + d1) / k, 0., 1.);
    return mix(d2, -d1, h) + k * h * (1. - h);
}

float scene(vec3 p) {
    float d = 100000.;
    float t = iTime;

    p.x += cos((p.z * 2.2 + t * .2) * .5) * .2;
    p.y += sin((p.z * 1.2 + t * .1) * .5) * .2;
    p.z += t * 3.;
    p.xy *= rot(p.z * .08);

    vec3 p0 = p;

    vec3 rep = vec3(12., 12., 8.);
    // p.xyz -= rep * .5; // centering
    p = mod(p, rep) - rep * .5;    

    vec3 pp = p;
    // pp.xy *= rot(sin(t * 1.2) * .1);

    d = opSmooth(d, sdBox(pp - vec3(0., 0., 0.), vec3(5., 2., 4.)), .5);
    d = opSmooth(d, sdBox(pp - vec3(0., 0., 0.), vec3(2., 5., 2.)), .5);
    d = opSmooth(d, sdBox(pp - vec3(0., 0., 0.), vec3(3., 4., 8.)), .5);

    float subs = .08;
    float subsm = .04;

    // p0.xy *= rot(sin(t * .2) * 0.);

    vec3 rqs = vec3(10., .5, .5);
    d = opSmoothSub(sdBox(mod(p0 - vec3(.25, 0., .25), rqs) - rqs * .5, vec3(10., subs, subs)), d, subsm);

    rqs = vec3(.5, 10., .5);
    d = opSmoothSub(sdBox(mod(p0 - vec3(.25, 0., .25), rqs) - rqs * .5, vec3(subs, 10., subs)), d, subsm);

    rqs = vec3(.5, .5, 10.);
    d = opSmoothSub(sdBox(mod(p0 - vec3(.25, .25, 0.), rqs) - rqs * .5, vec3(subs, subs, 10.)), d, subsm);

    p0.xy -= 0.;

    p.xy = pmod(p0.xy, 7.);    

    for(float i = 0.; i < 5.; i++) {
        vec3 q = p;
        q.z -= 1. * i;
        q.y -= .95 * (i + 1.3);
        vec3 _q = q;
        _q.yz *= rot(t * 1.8);
        d = opSmooth(d, sdBox(_q, vec3(5., .4, .4)), .9);
        p = q;
    }

    return d;
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(EPS, 0);
    return normalize(
    	vec3(
            scene(p + e.xyy) - scene(p - e.xyy),
            scene(p + e.yxy) - scene(p - e.yxy),
            scene(p + e.yyx) - scene(p - e.yyx)
        )
    );
}

vec2 raymarch(vec3 ro, vec3 rd) {
    float accDist = 0.;    
    float emission = 0.;

    for(int i = 0; i < 99; i++) {
        vec3 p = ro + rd * accDist;
        float dist = scene(p);
        emission += exp(abs(dist) * -.02); 
        if(dist < SURF_DIST || dist >= MAX_DIST) {
            break;
        }
        accDist += dist;                
    }

    return vec2(accDist, emission);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime;

    vec2 uv0 = fragCoord.xy / iResolution.xy;

    vec2 uv = (fragCoord.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);
    vec2 nmp = (iMouse.xy * 2. - iResolution.xy) / min(iResolution.x, iResolution.y);

    uv *= rot(sin(t * .1 + uv0.x * 1.2));

    vec3 ro = vec3(
        nmp.x * .1,
        nmp.y * .1,
        -5.
    );
    vec3 lookat = vec3(0.);
    vec3 forward = normalize(lookat - ro);
    vec3 right = normalize(cross(vec3(0., 1., 0.), forward));
    vec3 up = normalize(cross(forward, right));

    float zoom = 1.5;
    vec3 rd = normalize(right * uv.x + up * uv.y + forward * zoom);

    vec2 result = raymarch(ro, rd);
    float dist = result.x;
    float emission = result.y;

    vec3 col = vec3(0.);

    if(dist < MAX_DIST) {

        vec3 p = ro + rd * dist;
        vec3 lightDir = normalize(vec3(1., 1., -1.));

        vec3 normal = getNormal(p);    
        float diffuse = dot(lightDir, normal) * .5 + .5;

        col = diffuse * vec3(.4, .2, 1.);

        col += pow(TS(0., .1, .1, .2, mod(p.x + t * 0., 4.)), 8.) * vec3(.4, .2, 1.) * 4.;
        col += pow(TS(0., .1, .1, .2, mod(p.y + t * 0., 4.)), 8.) * vec3(.4, .2, 1.) * 4.;
        col += pow(TS(0., .1, .1, .2, mod(p.z + t * 4., 1.)), 8.) * vec3(.4, .2, 1.) * 4.;
    }

    col += emission * vec3(.4, .5, 1.) * .15;


    col *= exp(dist * -.35);

    col = mix(col, vec3(.3, .2, 1.), vec3(uv0.y + .15) * .15);
    col = mix(col, vec3(1., .2, .5), vec3(-uv0.y + .35) * .25);

    col = pow(col, vec3(.4545));

    fragColor = vec4(col, 1.);
}
